/**
 * The types `save/currencies/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CurrencyBalancesSaveRow, CurrenciesSaveExtract
 * depends    —
 * used by    src/save/currencies/index, src/save/currencies/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/** Balances the player holds now. Null where the save does not record that currency. */
export interface CurrencyBalancesSaveRow {
  coins: number | null
  gems: number | null
  stones: number | null
  medals: number | null
  cells: number | null
  keys: number | null
  tokens: number | null
  bits: number | null
  rerollShards: number | null
  cannonShards: number | null
  armorShards: number | null
  generatorShards: number | null
  coreShards: number | null
  moduleTickets: number | null
}

export interface CurrenciesSaveExtract {
  balances: CurrencyBalancesSaveRow
  /** Earned this cycle, keyed as the game names each currency (`coin`, `gem`, `module_reroll`…). */
  earnedThisCycle: Record<string, number>
  /** Spent this cycle, keyed the same way. */
  spentThisCycle: Record<string, number>
  warnings: string[]
}
